  /* link SkyNet parts / kit SKUs by part number */
  UPDATE public.price_items i SET part_id = p.id FROM public.parts p WHERE i.book_id = v_b81 AND i.part_id IS NULL AND upper(regexp_replace(p.part_number, '\s', '', 'g')) = i.part_key;
  UPDATE public.price_items i SET kit_sku_id = k.id FROM public.kit_skus k WHERE i.book_id = v_b81 AND i.kit_sku_id IS NULL AND upper(regexp_replace(k.part_number, '\s', '', 'g')) = i.part_key;
