  v_b82 := public.pricing_clone_book(v_b81, 'Rev 82 — Oct 2026', '2026-10-01', 0.15, 'Oct 1 2026 increase: every catalog Each x1.15; resale unchanged');
  PERFORM public.pricing_publish_book(v_b82, '2026-10-01');

  SELECT count(*) INTO n_items FROM public.price_items WHERE book_id = v_b81;
  SELECT count(*) INTO n_kits  FROM public.price_kit_components kc JOIN public.price_items i ON i.id = kc.item_id WHERE i.book_id = v_b81;
  SELECT count(*) INTO n_sec   FROM public.price_sections WHERE book_id = v_b81;
  RAISE NOTICE 'Rev 81 % / Rev 82 %: sections=% items=% kit_components=% expected items=4454 kit_components=48', v_b81, v_b82, n_sec, n_items, n_kits;
  IF v_dry_run THEN
    RAISE EXCEPTION 'DRY RUN OK — sections=% items=% kit_components=% (rolled back; set v_dry_run := false to apply)', n_sec, n_items, n_kits;
  END IF;
